--
-- Table structure for table `invoice_data`
--

CREATE TABLE `invoice_data` (
  `id` int(10) NOT NULL,
  `invoice_url` varchar(1000) DEFAULT NULL,
  `invoicedata` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`invoicedata`)),
  `restaurant_name` varchar(1000) NOT NULL,
  `restaurant_id` int(100) NOT NULL,
  `table_name` varchar(1000) DEFAULT NULL,
  `table_id` int(100) NOT NULL,
  `order_id` int(100) NOT NULL,
  `customer_code` varchar(1000) NOT NULL,
  `payment_mode` varchar(1000) DEFAULT NULL,
  `status` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

