--
-- Table structure for table `items`
--

CREATE TABLE `items` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `item_name` varchar(255) NOT NULL,
  `item_name_gu` varchar(255) DEFAULT NULL,
  `description` varchar(255) NOT NULL,
  `price` int(11) NOT NULL,
  `ac_price` int(11) DEFAULT NULL,
  `food_type` tinyint(4) NOT NULL,
  `picture` varchar(255) NOT NULL,
  `category_id` int(10) UNSIGNED NOT NULL,
  `restaurant_id` int(10) UNSIGNED NOT NULL,
  `status` tinyint(1) DEFAULT NULL,
  `availability_hours` decimal(5,3) DEFAULT NULL,
  `availability_set_at` timestamp NULL DEFAULT NULL,
  `display_in_ac` tinyint(4) DEFAULT NULL,
  `display_in_non_ac` tinyint(4) DEFAULT NULL,
  `fulfillment_type` enum('kitchen','service','','') NOT NULL DEFAULT 'kitchen',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

